selector_to_html = {"a[href=\"agent_discovery_routes_enhanced/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.agent_discovery_routes_enhanced<a class=\"headerlink\" href=\"#module-dataflow.api.routes.agent_discovery_routes_enhanced\" title=\"Link to this heading\">\u00b6</a></h1><p>Fixed Agent Discovery Routes using Haive Core\u2019s unified discovery system.</p><p>This module provides FastAPI routes for discovering and managing agents using the\nunified discovery system from haive-core. It replaces the previous implementation\nthat had duplicated discovery logic.</p>", "a[href=\"games/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.games<a class=\"headerlink\" href=\"#module-dataflow.api.routes.games\" title=\"Link to this heading\">\u00b6</a></h1><p>Games module.</p>", "a[href=\"agent_discovery_routes/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.agent_discovery_routes<a class=\"headerlink\" href=\"#module-dataflow.api.routes.agent_discovery_routes\" title=\"Link to this heading\">\u00b6</a></h1><p>Agent discovery and management API routes.</p><p>This module provides FastAPI routes for discovering and managing both v1 and v2 agents:\n- v1 agents: haive.engine.agent.config/agent (config-based agents)\n- v2 agents: haive.agents.base.agent (direct agent classes)</p>", "a[href=\"example_tool/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.example_tool<a class=\"headerlink\" href=\"#module-dataflow.api.routes.example_tool\" title=\"Link to this heading\">\u00b6</a></h1><p>Example tool for testing the tools API.</p>", "a[href=\"llm_routes/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.llm_routes<a class=\"headerlink\" href=\"#module-dataflow.api.routes.llm_routes\" title=\"Link to this heading\">\u00b6</a></h1><p>LLM model API routes and generation endpoints.</p><p>This module provides FastAPI routes for interacting with various LLM providers\nand models. It supports generating text completions, chat completions, and\nstreaming responses from models like OpenAI GPT, Anthropic Claude, Google Gemini,\nand others.</p>", "a[href=\"tools_routes/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.tools_routes<a class=\"headerlink\" href=\"#module-dataflow.api.routes.tools_routes\" title=\"Link to this heading\">\u00b6</a></h1><p>Tools API routes for discovering and listing available tools.</p><p>This module provides FastAPI routes for discovering and listing all\navailable tools in the Haive ecosystem. It scans the haive-tools package\nand returns information about available tools and toolkits.</p>", "a[href=\"#module-dataflow.api.routes\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes<a class=\"headerlink\" href=\"#module-dataflow.api.routes\" title=\"Link to this heading\">\u00b6</a></h1><p>Routes - TODO: Add brief description.</p><p>TODO: Add detailed description of module functionality</p>", "a[href=\"tools_routes_fixed/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.tools_routes_fixed<a class=\"headerlink\" href=\"#module-dataflow.api.routes.tools_routes_fixed\" title=\"Link to this heading\">\u00b6</a></h1><p>Tools API routes using the unified discovery system.</p><p>This module provides FastAPI routes for discovering and listing all\navailable tools in the Haive ecosystem using the haive-core discovery\nsystem.</p>", "a[href=\"conversation_routes/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.conversation_routes<a class=\"headerlink\" href=\"#module-dataflow.api.routes.conversation_routes\" title=\"Link to this heading\">\u00b6</a></h1><p>Conversation management API routes.</p><p>This module provides FastAPI routes for managing conversations between users\nand agents. It supports operations like creating, listing, retrieving, and\ndeleting conversations, as well as adding messages to existing conversations.</p>", "a[href=\"agent_discovery_routes_fixed/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.agent_discovery_routes_fixed<a class=\"headerlink\" href=\"#module-dataflow.api.routes.agent_discovery_routes_fixed\" title=\"Link to this heading\">\u00b6</a></h1><p>Agent discovery and management API routes using unified discovery system.</p><p>This module provides FastAPI routes for discovering and managing agents\nusing the haive-core discovery system.</p>", "a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"tools_routes_enhanced/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.tools_routes_enhanced<a class=\"headerlink\" href=\"#module-dataflow.api.routes.tools_routes_enhanced\" title=\"Link to this heading\">\u00b6</a></h1><p>Enhanced Tools Discovery API Routes using Haive Core\u2019s unified discovery\nsystem.</p><p>This module provides FastAPI routes for discovering, managing, and invoking tools\nusing the unified discovery system from haive-core. It supports both individual\ntools and toolkits with comprehensive schema extraction.</p>", "a[href=\"agent_routes/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.api.routes.agent_routes<a class=\"headerlink\" href=\"#module-dataflow.api.routes.agent_routes\" title=\"Link to this heading\">\u00b6</a></h1><p>WebSocket and REST API endpoints for agent interactions.</p><p>This module provides WebSocket-based communication with Haive agents, enabling\nreal-time interactions, streaming responses, and persistent conversation state.\nIt also includes REST endpoints for agent management and configuration.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
